// Copies the data the Worker shares with the CRM page (built-in team, stages, cities, email templates, offices, team phones, Group Review
// arrival notes) out of src/pages/app.html into src/shared.generated.ts, so emails and calendar invites use the
// exact wording the CRM shows. Run after replacing src/pages/app.html: `npm run extract`.
import fs from 'node:fs';
import vm from 'node:vm';

const root = new URL('..', import.meta.url);
const html = fs.readFileSync(new URL('src/pages/app.html', root), 'utf8');
const NAMES = ['TEAM', 'STAGES', 'OFFICES', 'CITIES', 'TEAM_PHONES', 'GR_ARRIVE', 'TEMPLATES'];

// Find `const NAME = ` and return the literal after it, matching brackets and skipping strings.
function literal(name) {
  const at = html.indexOf(`const ${name} = `);
  if (at < 0) throw new Error(`${name} not found in app.html`);
  let i = at + `const ${name} = `.length;
  const start = i; let depth = 0;
  for (; i < html.length; i++) {
    const ch = html[i];
    if (ch === '"' || ch === "'" || ch === '`') {
      for (i++; i < html.length && html[i] !== ch; i++) {
        if (html[i] === '\\') i++;
        else if (ch === '`' && html[i] === '$' && html[i + 1] === '{') throw new Error(`${name} has a template expression; extend this script`);
      }
      continue;
    }
    if (ch === '{' || ch === '[' || ch === '(') depth++;
    else if (ch === '}' || ch === ']' || ch === ')') { depth--; if (depth === 0) return html.slice(start, i + 1); }
  }
  throw new Error(`${name} never closes`);
}

const out = {};
for (const name of NAMES) out[name] = vm.runInNewContext(`(${literal(name)})`, {});

const body = NAMES.map((n) => `export const ${n} = ${JSON.stringify(out[n], null, 2)};`).join('\n\n');
fs.writeFileSync(new URL('src/shared.generated.ts', root), `// Generated by scripts/extract-shared.mjs from src/pages/app.html. Do not edit by hand.\n\n${body}\n`);
console.log('wrote src/shared.generated.ts:', NAMES.map((n) => `${n} (${Object.keys(out[n]).length})`).join(', '));
